#!/usr/bin/env node
/**
 * fixtures/m4/templates/tools/generate-fixtures.mjs
 *
 * Deterministic generator for the packet-65 M4 template fixtures
 * (`docs/planning/m4-contracts/templates.md`, Gate Q PROPOSAL). No network,
 * no eval, no third-party bytes: every generated byte is either original
 * content written here or a byte-identical copy of the committed
 * self-generated Beacon Reach sample assets (`samples/beacon-reach/assets/`,
 * whose provenance is committed there — templates.md §10).
 *
 * Writes (under fixtures/m4/templates/):
 *   templates/platformer-starter/...   the complete built-in template
 *                                      (descriptor.json, base/scene.json,
 *                                       recipe/commands.json, sources/**,
 *                                       NOTICE)
 *   cases/*.json                       the fixture case files (replay,
 *                                      identity, failures, layout, modules)
 *   index.json                         byte length + SHA-256 of every file
 *
 * The recipe is derived from the accepted Beacon Reach recipe
 * (`samples/beacon-reach/recipe/commands.json` — the 26 accepted commands):
 * the template's own game text (setGameConfig), then the packet-65
 * additions — one modelAnimation binding (command 27), one createPrefab
 * (28) and two independent instantiatePrefab instances (29, 30). N = 30.
 *
 * Re-running reproduces every byte exactly; `--check` verifies the on-disk
 * tree instead of writing. The INDEPENDENT checker (check-fixtures.mts,
 * run under tsx) re-derives the recipe replay through the real
 * @thirdlight/commands engine and every digest — it does not trust the
 * generator.
 */

import { createHash } from 'node:crypto';
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const FIXTURE_ROOT = resolve(HERE, '..');
const REPO_ROOT = resolve(HERE, '..', '..', '..', '..');
const CHECK = process.argv.includes('--check');

const sha256Hex = (buf) => createHash('sha256').update(buf).digest('hex');
/** The accepted block-digest rule (sessions.md §17.1.1): canonical 2-space
 *  JSON + one trailing LF, over the document as committed. */
const blockDigestOf = (value) => sha256Hex(Buffer.from(`${JSON.stringify(value, null, 2)}\n`, 'utf8'));

const TEMPLATE_ID = 'platformer-starter';
const TEMPLATE_VERSION = 1;
const ENGINE_VERSION = '0.1.0';
const TEMPLATE_NAME = 'Platformer Starter';

// ---------------------------------------------------------------------------
// 1. The base scene (templates.md §3 — normative; the exact bytes)
// ---------------------------------------------------------------------------

const BASE_SCENE = {
  schemaVersion: 3,
  sceneId: 'scene-main',
  revision: 0,
  entities: [
    {
      id: 'br-cam-main',
      name: 'Gameplay camera',
      components: {
        transform: { position: [0, 4, 12], rotation: [0, 0, 0, 1], scale: [1, 1, 1] },
        camera: { type: 'perspective', fovY: 45, near: 0.1, far: 100 },
        cameraFollow: {
          deadZone: { x: 0.5, y: 0.5 },
          smoothing: 0.2,
          bounds: { minX: 0, maxX: 48, minY: -10, maxY: 8 },
        },
      },
    },
  ],
};

// ---------------------------------------------------------------------------
// 2. The starter recipe (templates.md §4) — derived from the accepted sample
// ---------------------------------------------------------------------------

const SAMPLE_RECIPE_PATH = join(REPO_ROOT, 'samples/beacon-reach/recipe/commands.json');
const sampleRecipe = JSON.parse(readFileSync(SAMPLE_RECIPE_PATH, 'utf8'));
if (sampleRecipe.commands.length !== 26) {
  throw new Error(`expected the accepted sample recipe to carry 26 commands, got ${sampleRecipe.commands.length} — the derivation premise changed; do not edit silently`);
}
// Whitelist sanity of the SAMPLE commands (templates.md §4.1): the sample
// uses publishAsset/createEntity/setGameConfig/setSettings — all whitelisted.
const WHITELIST = new Set(['publishAsset', 'createEntity', 'setTransform', 'setComponent', 'createPrefab', 'instantiatePrefab', 'setGameConfig', 'setSettings']);
for (const c of sampleRecipe.commands) {
  if (!WHITELIST.has(c.op)) throw new Error(`sample recipe op outside the template whitelist: ${c.op}`);
}
const baseCommands = sampleRecipe.commands.map((c) => ({ op: c.op, args: c.args }));

// The template's own game text (the sample's layout/IDs/cues are kept —
// the derivation, templates.md §1.2):
const setGameConfigIdx = baseCommands.findIndex((c) => c.op === 'setGameConfig');
if (setGameConfigIdx < 0) throw new Error('the sample recipe must contain a setGameConfig');
const sampleGame = baseCommands[setGameConfigIdx].args.game;
baseCommands[setGameConfigIdx] = {
  op: 'setGameConfig',
  args: {
    game: {
      ...sampleGame,
      title: 'Platformer Starter',
      objective: 'Reach the beacon across the course',
    },
  },
};

// The packet-65 additions (N becomes 30):
const RECIPE = {
  templateId: TEMPLATE_ID,
  baseScene: 'base/scene.json',
  commands: [
    ...baseCommands,
    // 27 — visible animated content: bind the courier's clips (Idle=0,
    // Run=1, Airborne=2 — the committed courier.glb clip order).
    {
      op: 'setComponent',
      args: {
        entityId: 'model-0001',
        component: 'modelAnimation',
        value: {
          assetId: 'br-model-courier',
          version: 1,
          roles: {
            idle: { clipIndex: 0, clipName: 'Idle' },
            run: { clipIndex: 1, clipName: 'Run' },
            airborne: { clipIndex: 2, clipName: 'Airborne' },
          },
        },
      },
    },
    // 28 — the decoration prefab definition (Gate P F4/B17 closure: the
    // template carries two independent decoration prefab instances).
    {
      op: 'createPrefab',
      args: { prefabId: 'prefab-0001', displayName: 'Beacon Decoration', sourceEntityId: 'model-0002' },
    },
    // 29/30 — two independent instances (deterministic IDs model-0004 /
    // model-0005 — model-0003 is the sample's pillar B).
    { op: 'instantiatePrefab', args: { prefabId: 'prefab-0001', transform: { position: [8, 0, 0] } } },
    { op: 'instantiatePrefab', args: { prefabId: 'prefab-0001', transform: { position: [32, 0, 0] } } },
  ],
};
const N = RECIPE.commands.length;
if (N !== 30 || N > 128) throw new Error(`recipe bound violated: N=${N}`);

// ---------------------------------------------------------------------------
// 3. The source blobs (the committed self-generated sample assets, byte-
//    identical; the descriptor inventory is sorted by path)
// ---------------------------------------------------------------------------

const ASSETS_SRC = join(REPO_ROOT, 'samples/beacon-reach/assets');
const BLOB_PATHS = [
  'audio/cue-checkpoint.wav',
  'audio/cue-death.wav',
  'audio/cue-goal.wav',
  'audio/cue-jump.wav',
  'audio/cue-start.wav',
  'model/beacon.glb',
  'model/courier.glb',
];
const blobs = BLOB_PATHS.map((p) => {
  const buf = readFileSync(join(ASSETS_SRC, p));
  return { path: p, digest: sha256Hex(buf), byteLength: buf.length };
});
blobs.sort((a, b) => (a.path < b.path ? -1 : 1));
if (blobs.length > 64) throw new Error('template blob bound violated');

// ---------------------------------------------------------------------------
// 4. The descriptor (templates.md §1 — digests computed, §1.3)
// ---------------------------------------------------------------------------

const descriptor = {
  schemaVersion: 1,
  type: 'thirdlight-template',
  templateId: TEMPLATE_ID,
  name: TEMPLATE_NAME,
  version: TEMPLATE_VERSION,
  engineVersion: ENGINE_VERSION,
  recipeDigest: blockDigestOf(RECIPE),
  baseDigest: blockDigestOf(BASE_SCENE),
  contentDigest: null, // filled below (the digest input excludes this field)
  blobs,
  modules: {
    required: ['thirdlight.platformer:controller', 'thirdlight.platformer-game:session', 'thirdlight.platformer-game:camera'],
    optional: [],
  },
  layout: {
    layoutVersion: 1,
    panels: {
      hierarchy: { visible: true },
      inspector: { visible: true },
      assets: { visible: true },
      media: { visible: true },
      prefabs: { visible: true },
      behaviors: { visible: true },
      gameplay: { visible: true },
    },
  },
  provenance: {
    derivedFrom: 'samples/beacon-reach',
    note:
      'M4 built-in platformer template (templates.md §1.2). Derived from the accepted Beacon Reach recipe (samples/beacon-reach/recipe/commands.json, 26 commands): the layout and self-generated assets are reused byte-identically; the game text is the template\\u2019s own; commands 27\\u201330 add the courier modelAnimation binding, the beacon decoration prefab and two independent instances. The source content is engine-generated (NOTICE).',
  },
};
const descriptorMinusDigest = { ...descriptor, contentDigest: undefined };
// canonical key order per templates.md §1.1:
const canonicalDescriptor = {
  schemaVersion: descriptorMinusDigest.schemaVersion,
  type: descriptorMinusDigest.type,
  templateId: descriptorMinusDigest.templateId,
  name: descriptorMinusDigest.name,
  version: descriptorMinusDigest.version,
  engineVersion: descriptorMinusDigest.engineVersion,
  recipeDigest: descriptorMinusDigest.recipeDigest,
  baseDigest: descriptorMinusDigest.baseDigest,
  blobs: descriptorMinusDigest.blobs,
  modules: descriptorMinusDigest.modules,
  layout: descriptorMinusDigest.layout,
  provenance: descriptorMinusDigest.provenance,
};
descriptor.contentDigest = blockDigestOf(canonicalDescriptor);
const descriptorDoc = { ...canonicalDescriptor, contentDigest: descriptor.contentDigest };

// ---------------------------------------------------------------------------
// 5. The NOTICE (templates.md §10)
// ---------------------------------------------------------------------------

const NOTICE = `Platformer Starter template — provenance and license
=====================================================

Content: engine-generated (original generated content of the Thirdlight
campaign). No downloaded asset, no third-party bytes; no license is
asserted over external material.

Derivation: this template is derived from the accepted Beacon Reach sample
recipe (samples/beacon-reach/recipe/commands.json — 26 commands, committed
with its generation tooling and asset provenance under samples/beacon-reach/).
The source assets below are byte-identical copies of the sample's
self-generated assets (samples/beacon-reach/assets/); their generation
scripts and provenance JSON are committed there. The recipe reuses the
sample's layout commands with the template's own game text (commands 1-26)
and adds (27-30) the courier modelAnimation binding, one decoration prefab
definition and two independent decoration prefab instances.

Digests: the descriptor's "blobs" inventory lists every source file with
its SHA-256 digest and byte length; the descriptor's recipeDigest/baseDigest/
contentDigest follow the accepted block-digest rule (SHA-256 of the canonical
2-space JSON + one trailing LF of the committed document; contentDigest over
the descriptor without its own contentDigest field).

Distribution: this directory is engine content (part of the engine
distribution; the packet-66 engine-kit layout owns its in-kit location).
Creating a project copies these bytes into the project's own content store
— the project never references this directory after creation.
`;

// ---------------------------------------------------------------------------
// 6. Case files (templates.md §14)
// ---------------------------------------------------------------------------

// The deterministic requestIds (templates.md §7.1): req- + first 32 hex of
// sha256("<templateId>@<version>#<i>") — recorded so the 72/73 evidence can
// pin the exact retry records without re-implementing the derivation.
const recipeRequestIds = RECIPE.commands.map((_, i) =>
  `req-${sha256Hex(Buffer.from(`${TEMPLATE_ID}@${TEMPLATE_VERSION}#${i + 1}`, 'utf8')).slice(0, 32)}`
);
for (const id of recipeRequestIds) {
  if (!/^req-[0-9a-f]{32}$/.test(id)) throw new Error(`requestId shape violated: ${id}`);
}

// The final envelope facts the replay must produce (the checker RE-DERIVES
// every one through the real engine — these are the pinned expectations):
const FINAL_ENTITY_IDS = [
  'br-cam-main', 'box-0001', 'box-0002', 'box-0003', 'box-0004', 'spawn-0001',
  'box-0005', 'box-0006', 'box-0007', 'box-0008', 'box-0009', 'group-0001',
  'spawn-0002', 'light-0001', 'light-0002', 'model-0001', 'model-0002',
  'model-0003', 'model-0004', 'model-0005',
];

const RECIPE_CASES = {
  description:
    'The command-recipe validity cases (templates.md §14.2). The checker re-derives the final envelope from (base scene + recipe) through the real @thirdlight/commands engine (the accepted capture-tool pattern) and asserts every fact here; a mismatch is a fixture failure.',
  n: N,
  recipeRequestIds,
  // The post-promotion origin form (C65-7): the accepted engine's origin
  // validation (browser | mcp | admin) does not yet include `template`, so
  // the checker's engine replay uses the documented `kind: "admin"`
  // substitution (templates.md §7.1) — an audit tag with no semantic
  // effect on the accepted pipeline.
  origin: { kind: 'template', clientId: `${TEMPLATE_ID}@${TEMPLATE_VERSION}`, replaySubstitution: { kind: 'admin', note: 'pre-promotion engine replay; templates.md §7.1' } },
  baseScene: BASE_SCENE,
  baseContent: { assets: [], prefabs: [], behaviors: [], settings: {}, behaviorTrust: { entries: [] }, game: null },
  replay: {
    everyCommandApplies: true,
    finalRevision: N,
    entityIds: FINAL_ENTITY_IDS,
    entityCount: FINAL_ENTITY_IDS.length,
    assetIds: ['br-audio-checkpoint', 'br-audio-death', 'br-audio-goal', 'br-audio-jump', 'br-audio-start', 'br-model-beacon', 'br-model-courier'],
    prefabIds: ['prefab-0001'],
    // The stored settings map is canonical (alphabetical — project-model
    // §12.2), distinct from the §21.4 registry-table order the packet-64
    // querySettings result uses: gravity_y, run_speed, jump_velocity, …
    settings: { gravity_y: -19.62, jump_velocity: 7, max_fall_speed: -30, max_slope_climb_deg: 45, min_slope_slide_deg: 30, run_speed: 4 },
    game: {
      configVersion: 1,
      title: 'Platformer Starter',
      objective: 'Reach the beacon across the course',
      instructions: sampleGame.instructions,
      playerId: sampleGame.playerId,
      cameraId: sampleGame.cameraId,
      spawnId: sampleGame.spawnId,
      level: sampleGame.level,
      killY: sampleGame.killY,
      cues: sampleGame.cues,
    },
  },
  prefabIndependence: {
    description: 'the two instantiatePrefab results are independent entities with distinct IDs, each carrying the prefab provenance component; editing one never touches the other (the Gate P F4/B17 closure — the in-browser edit-independence evidence is 81).',
    instanceIds: ['model-0004', 'model-0005'],
    positions: [[8, 0, 0], [32, 0, 0]],
    prefabComponent: { prefabId: 'prefab-0001' },
    distinctFromSource: true, // the instances are copies of model-0002's value (the prefab definition), not references to it
  },
  animatedContent: {
    description: 'visible animated content (templates.md §1.2): the courier carries modelAnimation bound to its committed clips; the binding is version-local (version 1) and the clip indices/names match the committed courier.glb animation order.',
    entityId: 'model-0001',
    assetId: 'br-model-courier',
    version: 1,
    roles: { idle: { clipIndex: 0, clipName: 'Idle' }, run: { clipIndex: 1, clipName: 'Run' }, airborne: { clipIndex: 2, clipName: 'Airborne' } },
    glbClipOrder: ['Idle', 'Run', 'Airborne'], // the committed samples/beacon-reach/assets/model/courier.glb animation order
  },
};

const IDENTITY_CASES = {
  description:
    'The identity-independence cases (templates.md §14.3; C04/C05). The checker re-derives: (a) two creations from the same template (different projectIds) share the internal IDs (deterministic replay) and differ in every identity-bearing field; (b) the v2 replacement identity (changed game text ⇒ new digests) and the old-project-unchanged invariant.',
  twoCreations: {
    sameTemplate: { templateId: TEMPLATE_ID, version: TEMPLATE_VERSION, contentDigest: descriptor.contentDigest },
    creationA: { projectId: 'starter-0001', name: 'My Platformer' },
    creationB: { projectId: 'starter-0002', name: 'Second Platformer' },
    invariants: {
      internalEntityIds: 'equal (the deterministic <kind>-NNNN allocations over the identical base scene + recipe — project-scoped reuse, m4-plan §2.1)',
      internalAssetIds: 'equal (the recipe-authored assetIds)',
      distinct: ['projectId', 'manifest.id', 'manifest.name', 'manifest.createdAt (each creation time)', 'envelope.projectId', 'ownership record (claim)'],
      crossProjectReference: 'not expressible (the accepted project-scoped ID model)',
    },
    manifestTemplateBlock: {
      templateId: TEMPLATE_ID,
      version: TEMPLATE_VERSION,
      contentDigest: descriptor.contentDigest,
      engineVersion: ENGINE_VERSION,
    },
  },
  replacement: {
    description: 'an operator replaces the installed template with version 2 (the game text changes ⇒ new recipeDigest/contentDigest). New creations record the v2 identity; created projects are unaffected (templates.md §5.4).',
    v2: {
      version: 2,
      changed: 'the setGameConfig command\\u2019s game.title only ("Platformer Starter v2") — everything else byte-identical',
      recipe: (function () {
        const v2 = JSON.parse(JSON.stringify(RECIPE));
        const idx = v2.commands.findIndex((c) => c.op === 'setGameConfig');
        v2.commands[idx].args.game.title = 'Platformer Starter v2';
        return v2;
      })(),
      recipeDigest: null, // filled below
      contentDigest: null, // filled below (the descriptor with version 2 + the new recipeDigest)
    },
    rules: [
      'a creation after the replacement records the v2 identity (manifest template.version 2, v2 contentDigest)',
      'a creation before it (or a retry of the same identity) keeps the v1 identity',
      'a created v1 project reopens/builds/Plays unchanged after the replacement (no live template reference)',
      'an in-flight creation whose marker digest is v1 when only v2 is installed ⇒ template_source_unavailable (never re-pointed)',
    ],
  },
};
{
  const v2 = IDENTITY_CASES.replacement.v2;
  v2.recipeDigest = blockDigestOf(v2.recipe);
  const v2Descriptor = { ...descriptorDoc, version: 2, recipeDigest: v2.recipeDigest, contentDigest: undefined };
  const v2Canonical = {
    schemaVersion: v2Descriptor.schemaVersion,
    type: v2Descriptor.type,
    templateId: v2Descriptor.templateId,
    name: v2Descriptor.name,
    version: v2Descriptor.version,
    engineVersion: v2Descriptor.engineVersion,
    recipeDigest: v2Descriptor.recipeDigest,
    baseDigest: v2Descriptor.baseDigest,
    blobs: v2Descriptor.blobs,
    modules: v2Descriptor.modules,
    layout: v2Descriptor.layout,
    provenance: v2Descriptor.provenance,
  };
  v2.contentDigest = blockDigestOf(v2Canonical);
}

const FAILURE_CASES = {
  description:
    'The failure-phase cases (templates.md §14.4; C09). One case per new code with the exact raising state. The checker re-derives the pure parts (digests, recipe rules, resolution); the workspace-phase states (marker/on-disk) are the pinned 72/73 evidence expectations.',
  cases: [
    { id: 'F1', code: 'template_not_found', state: 'creation names a templateId not in the installed verified set (removed, or never installed)', resolution: 'nothing written; the install scan row reports the installed set only' },
    { id: 'F2', code: 'template_descriptor_invalid', state: 'a descriptor with an unknown field, a wrong schemaVersion/type, or a blobs entry unsorted / with an invalid path (.., escape, or a symlink component)', resolution: 'install scan reports + excludes the template; creation naming it ⇒ template_not_found (never loaded)' },
    { id: 'F3', code: 'template_content_mismatch', state: 'any of the three digest checks fails: descriptor-minus-digest re-hash ≠ contentDigest; recipe re-hash ≠ recipeDigest; a sources file re-hash/length ≠ its inventory row (a tampered file)', resolution: 'the template is refused for creation and reported by the scan; no field is ever repaired from another field' },
    { id: 'F4', code: 'template_engine_version_mismatch', state: 'backend engineVersion ≠ the descriptor engineVersion (carries both)', resolution: 'creation refused before the reserved phase (nothing written)' },
    { id: 'F5', code: 'template_path_rejected', state: 'a template file path escapes templatesRoot, uses .., or any path component is a symlink (realpath containment fails)', resolution: 'the template is refused at install scan (and at creation); the symlink case is never followed' },
    { id: 'F6', code: 'template_recipe_invalid', state: 'three sub-cases: (a) an op outside the §4.1 whitelist (e.g. deleteEntity or publishBehavior — the behavior boundary, templates.md §4.1/§8.4); (b) a bound (N > 128, recipe > 256 KiB, blobs > 64); (c) a replayed command fails validation at creation (a command index i fails ⇒ the error carries index i + the command error)', resolution: '(a)/(b) at install scan (the template is refused — a committed recipe that does not replay is invalid, §4.3); (c) at the replayed phase (the marker is retained at the last good command; the destination stays resumable/deletable, never ready)' },
    { id: 'F7', code: 'template_destination_exists', state: 'the destination exists with a different identity: different template/digest, different name, a non-template (v1-manifest or migrated) project, a partial destination of a different identity, or an unloadable directory (carries existing: project|partial|unloadable)', resolution: 'nothing written; the existing project is never overwritten/renamed/upgraded; the identity-matching retry is the §5.2 no-op (created:false)' },
    { id: 'F8', code: 'template_reservation_conflict', state: 'a foreign reservation marker (different identity) is observed for the same destination at the reserved phase (concurrent different-identity claim)', resolution: 'the loser is refused; the winner proceeds; no marker is overwritten' },
    { id: 'F9', code: 'template_marker_conflict', state: 'the marker and the on-disk state disagree unrecoverably: recipeApplied ≠ the envelope revision; a corrupt published phase at revision < N; a manifest that does not re-derive from the reservation identity', resolution: 'no auto-completion; the scan reports; the operator deletes the destination (or resumes when the disagreement is a simple resume gap)' },
    { id: 'F10', code: 'template_initialization_incomplete', state: 'any open/query/Play/project-list against a destination with a marker phase < published (carries phase, recipeApplied, the resume/delete hint)', resolution: 'the destination is not a project: it never appears as loadable; only the published+claimed+marker-removed state is ready (the C09 invariant)' },
    { id: 'F11', code: 'template_source_unavailable', state: 'an in-flight creation (marker phase < published) whose marker templateContentDigest matches no installed template (a replacement landed across a crash)', resolution: 'reported by the scan; resolved by restoring the original template (then resume) or deleting the destination; never re-pointed, never auto-completed' },
    { id: 'F12', code: 'module_unknown', state: 'a declared or content-derived module ID is not in the finite §8.1 registry (at any evaluation point §8.3)', resolution: 'creation fails before published (reported at the marker); capture/export fail the snapshot build with the exact code; post-edit Play is refused with it' },
    { id: 'F13', code: 'module_duplicate', state: 'the resolved set would contain the same ID twice (a registry-integrity fault — the resolution is a set union over a flat registry, so this is a registry-validation failure)', resolution: 'fail-fast before publication/build' },
    { id: 'F14', code: 'module_cycle', state: 'the registry dependency edges carry a cycle (impossible for the flat M4 registry — a registry-integrity check specified so a future row cannot smuggle one in)', resolution: 'fail-fast before publication/build' },
    { id: 'F15', code: 'module_unresolved', state: 'the delivery capture of a scene whose content references thirdlight.behavior:<id> (a user-added behavior, §8.4): the module is referenced but not linkable under the M4 built-in-only profile', resolution: 'the capture fails with the exact code — never a silent omission (C14), never a silent fallback (the host fail-closed, CC-55-3a, is the same boundary at the host layer)' },
    { id: 'F16', code: 'manifest_storage_mismatch', state: 'a manifest schemaVersion 2 paired with storageVersion ≤ 2 (the §6 named-combination check)', resolution: 'the load pipeline refuses with version_combination_unsupported (single error); the only new valid combination is (2, 3, 3)' },
    { id: 'F17', code: 'content_quota_exceeded', state: 'the destination quota / device free space cannot hold the template blobs (checked before the blobs phase; kind: project_quota | device_space)', resolution: 'the reserved marker is retained; nothing half-published; resumable after space, operator-deletable' },
    { id: 'F18', code: 'content_publish_failed', state: 'a W failure (ENOSPC/EIO) in the blobs/envelope phases (the accepted content_publish_failed with the onDiskState)', resolution: 'the marker stays at the last completed phase; never half-claimed, never ready (§5.7)' },
  ],
  crashTable: 'the §5.6 phase table is the crash-completion spec; the 72/73 evidence drills each boundary (subprocess crash at reserved/blobs/envelope/replayed(K<N)/published-unclaimed) and asserts the no-ready-partial invariant (C09).',
};

